import { ProductDetail } from "@/registry/new-york/blocks/product-detail/components/product-detail";

export default function Page() {
  return (
    <div className="py-6 md:py-10">
      <ProductDetail />
    </div>
  );
}

"use client";

import * as React from "react";
import {
  Breadcrumb,
  BreadcrumbItem,
  BreadcrumbLink,
  BreadcrumbList,
  BreadcrumbPage,
  BreadcrumbSeparator,
} from "@/components/ui/breadcrumb";

import {
  product as defaultProduct,
  relatedProducts as defaultRelated,
  type Product,
  type RelatedProduct,
} from "@/registry/new-york/blocks/product-detail/lib/products";
import { ProductStoreProvider } from "@/registry/new-york/blocks/product-detail/components/product-store";
import { ProductGallery } from "@/registry/new-york/blocks/product-detail/components/product-gallery";
import { ProductSummary } from "@/registry/new-york/blocks/product-detail/components/product-summary";
import { ProductTabs } from "@/registry/new-york/blocks/product-detail/components/product-tabs";
import { RelatedProducts } from "@/registry/new-york/blocks/product-detail/components/related-products";
import { StickyBuyBar } from "@/registry/new-york/blocks/product-detail/components/sticky-buy-bar";

export function ProductDetail({
  product = defaultProduct,
  related = defaultRelated,
}: {
  product?: Product;
  related?: RelatedProduct[];
}) {
  return (
    <ProductStoreProvider product={product}>
      <div className="mx-auto w-full max-w-6xl px-4 pb-24 md:px-6 md:pb-12">
        {/* Breadcrumb */}
        <Breadcrumb className="py-4">
          <BreadcrumbList>
            {product.breadcrumb.map((crumb, i) => {
              const last = i === product.breadcrumb.length - 1;
              return (
                <React.Fragment key={crumb.label}>
                  <BreadcrumbItem>
                    {last ? (
                      <BreadcrumbPage>{crumb.label}</BreadcrumbPage>
                    ) : (
                      <BreadcrumbLink href={crumb.href}>
                        {crumb.label}
                      </BreadcrumbLink>
                    )}
                  </BreadcrumbItem>
                  {last ? null : <BreadcrumbSeparator />}
                </React.Fragment>
              );
            })}
          </BreadcrumbList>
        </Breadcrumb>

        {/* Gallery + summary: single column on mobile, two columns on md+ */}
        <div className="grid grid-cols-1 gap-8 md:grid-cols-2 lg:gap-12">
          <ProductGallery images={product.images} />
          <ProductSummary product={product} />
        </div>

        {/* Details tabs */}
        <div className="mt-12 md:mt-16">
          <ProductTabs product={product} />
        </div>

        {/* Related */}
        <div className="mt-12 md:mt-16">
          <RelatedProducts products={related} />
        </div>

        {/* Mobile sticky buy bar (shares the product store) */}
        <StickyBuyBar />
      </div>
    </ProductStoreProvider>
  );
}

"use client";

import * as React from "react";
import { toast } from "sonner";

import type { Product } from "@/registry/new-york/blocks/product-detail/lib/products";

type ProductStore = {
  product: Product;
  color: string | undefined;
  size: string | undefined;
  setColor: (id: string) => void;
  setSize: (id: string) => void;
  wishlisted: boolean;
  toggleWishlist: () => void;
  pending: boolean;
  /** True when a variant is chosen and the item is purchasable. */
  canAdd: boolean;
  addToCart: () => void;
};

const ProductStoreContext = React.createContext<ProductStore | null>(null);

export function ProductStoreProvider({
  product,
  children,
}: {
  product: Product;
  children: React.ReactNode;
}) {
  const [color, setColor] = React.useState<string | undefined>(
    product.colors[0]?.id
  );
  const [size, setSize] = React.useState<string>();
  const [wishlisted, setWishlisted] = React.useState(false);
  const [pending, setPending] = React.useState(false);

  const timer = React.useRef<ReturnType<typeof setTimeout>>(undefined);
  React.useEffect(() => () => clearTimeout(timer.current), []);

  const outOfStock = product.stock === "out-of-stock";
  const canAdd = Boolean(size) && !outOfStock;

  const addToCart = React.useCallback(() => {
    if (pending) return;
    if (outOfStock) {
      toast.error("This item is out of stock");
      return;
    }
    if (!size) {
      toast.error("Please choose a size first");
      return;
    }
    setPending(true);
    const colorName = product.colors.find((c) => c.id === color)?.name;
    timer.current = setTimeout(() => {
      setPending(false);
      toast.success("Added to cart", {
        description: `${product.name} · ${colorName} · Size ${size.toUpperCase()}`,
      });
    }, 1100);
  }, [pending, outOfStock, size, color, product]);

  const toggleWishlist = React.useCallback(() => {
    setWishlisted((prev) => {
      const next = !prev;
      if (next) {
        toast.success("Saved to wishlist", { description: product.name });
      } else {
        toast("Removed from wishlist");
      }
      return next;
    });
  }, [product.name]);

  const value = React.useMemo<ProductStore>(
    () => ({
      product,
      color,
      size,
      setColor,
      setSize,
      wishlisted,
      toggleWishlist,
      pending,
      canAdd,
      addToCart,
    }),
    [product, color, size, wishlisted, toggleWishlist, pending, canAdd, addToCart]
  );

  return (
    <ProductStoreContext.Provider value={value}>
      {children}
    </ProductStoreContext.Provider>
  );
}

export function useProductStore(): ProductStore {
  const ctx = React.useContext(ProductStoreContext);
  if (!ctx) {
    throw new Error(
      "useProductStore must be used within a ProductStoreProvider"
    );
  }
  return ctx;
}

"use client";

import { Loader2, ShoppingCart } from "lucide-react";

import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { formatPrice } from "@/registry/new-york/blocks/product-detail/lib/products";
import { PRESS } from "@/registry/new-york/blocks/product-detail/lib/motion";
import { useProductStore } from "@/registry/new-york/blocks/product-detail/components/product-store";

/**
 * Mobile-only sticky purchase bar. Shares the product store, so its Add to
 * cart drives the same pending → toast flow as the summary. It stays tappable
 * without a size and surfaces a toast prompting selection (never silent).
 */
export function StickyBuyBar() {
  const { product, pending, addToCart } = useProductStore();

  return (
    <div className="fixed inset-x-0 bottom-0 z-40 flex items-center gap-3 border-t bg-background/95 px-4 py-3 pb-[max(var(--space-3),env(safe-area-inset-bottom))] backdrop-blur md:hidden">
      <div className="flex flex-col">
        <span className="text-lg font-bold text-sale-price">
          {formatPrice(product.price, product.currency)}
        </span>
        <span className="text-xs text-muted-foreground line-through">
          {formatPrice(product.originalPrice, product.currency)}
        </span>
      </div>
      <Button
        size="lg"
        onClick={addToCart}
        disabled={pending}
        aria-busy={pending}
        className={cn("h-12 flex-1 text-base", PRESS)}
      >
        {pending ? <Loader2 className="animate-spin" /> : <ShoppingCart />}
        {pending ? "Adding…" : "Add to cart"}
      </Button>
    </div>
  );
}

"use client";

import * as React from "react";

import { cn } from "@/lib/utils";
import type { ProductImage } from "@/registry/new-york/blocks/product-detail/lib/products";
import {
  PRESS,
  TRANSITION,
} from "@/registry/new-york/blocks/product-detail/lib/motion";
import { ProductIcon } from "@/registry/new-york/blocks/product-detail/components/product-icon";

export function ProductGallery({ images }: { images: ProductImage[] }) {
  const [active, setActive] = React.useState(0);
  const current = images[active];

  return (
    // Rail below on mobile, beside on md+ (thumbnail rail returns at 768).
    <div className="flex flex-col-reverse gap-4 md:flex-row">
      {/* Thumbnail rail — horizontal scroll on mobile, vertical column on md+ */}
      <ul
        className="flex shrink-0 gap-3 overflow-x-auto pb-1 md:flex-col md:overflow-visible md:pb-0"
        aria-label="Product image thumbnails"
      >
        {images.map((image, i) => {
          const selected = i === active;
          return (
            <li key={image.id} className="shrink-0">
              <button
                type="button"
                onClick={() => setActive(i)}
                aria-label={`Show ${image.alt}`}
                aria-pressed={selected}
                className={cn(
                  "size-16 cursor-pointer overflow-hidden rounded-md border outline-none",
                  TRANSITION,
                  PRESS,
                  // Focus: offset ring. Selection: solid inset primary ring — distinct.
                  "focus-visible:ring-[3px] focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background",
                  selected
                    ? "border-primary ring-2 ring-primary"
                    : "border-border hover:border-primary/60"
                )}
              >
                <ProductIcon
                  icon={image.icon}
                  className="size-full rounded-none"
                  iconClassName="size-6"
                />
              </button>
            </li>
          );
        })}
      </ul>

      {/* Main image */}
      <div className="relative min-w-0 flex-1">
        <div className="aspect-square overflow-hidden rounded-xl border bg-muted">
          <ProductIcon
            icon={current.icon}
            className="size-full rounded-none"
            iconClassName="size-20"
          />
        </div>
        <span className="absolute right-3 bottom-3 rounded-full border bg-background/80 px-2.5 py-1 text-xs text-muted-foreground backdrop-blur">
          {active + 1} / {images.length} · {current.alt}
        </span>
      </div>
    </div>
  );
}

"use client";

import {
  Check,
  Heart,
  Loader2,
  RotateCcw,
  ShieldCheck,
  ShoppingCart,
  Truck,
} from "lucide-react";

import { cn } from "@/lib/utils";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { RadioGroup, RadioGroupItem } from "@/components/ui/radio-group";
import { Separator } from "@/components/ui/separator";
import {
  formatPrice,
  type Product,
  type StockStatus,
} from "@/registry/new-york/blocks/product-detail/lib/products";
import {
  FOCUS_RING,
  PRESS,
  TRANSITION,
} from "@/registry/new-york/blocks/product-detail/lib/motion";
import { StarRating } from "@/registry/new-york/blocks/product-detail/components/star-rating";
import { useProductStore } from "@/registry/new-york/blocks/product-detail/components/product-store";

const STOCK_LABELS: Record<StockStatus, { label: string; className: string }> = {
  "in-stock": { label: "In stock", className: "text-in-stock" },
  "low-stock": { label: "Low stock — order soon", className: "text-low-stock" },
  "out-of-stock": { label: "Out of stock", className: "text-out-of-stock" },
};

const TRUST_BADGES = [
  { icon: Truck, title: "Free shipping", detail: "On orders over $75" },
  { icon: ShieldCheck, title: "2-year warranty", detail: "Craftsmanship covered" },
  { icon: RotateCcw, title: "30-day returns", detail: "No-questions refunds" },
];

export function ProductSummary({ product }: { product: Product }) {
  const {
    color,
    size,
    setColor,
    setSize,
    wishlisted,
    toggleWishlist,
    pending,
    canAdd,
    addToCart,
  } = useProductStore();

  const stock = STOCK_LABELS[product.stock];
  const selectedColor = product.colors.find((c) => c.id === color);

  return (
    <div className="flex flex-col gap-6">
      {/* Category + title + rating */}
      <div className="flex flex-col gap-2">
        <span className="text-sm font-medium tracking-wide text-muted-foreground uppercase">
          {product.category}
        </span>
        <h1 className="text-3xl font-bold tracking-tight text-balance">
          {product.name}
        </h1>
        <div className="flex flex-wrap items-center gap-2 text-sm">
          <StarRating rating={product.rating} />
          <span className="font-medium">{product.rating.toFixed(1)}</span>
          <a
            href="#reviews"
            className={cn(
              "rounded-sm text-muted-foreground underline-offset-4 hover:text-foreground hover:underline",
              TRANSITION,
              FOCUS_RING
            )}
          >
            {product.reviewCount} reviews
          </a>
        </div>
      </div>

      {/* Short description */}
      <p className="text-sm text-muted-foreground">{product.shortDescription}</p>

      {/* Price */}
      <div className="flex flex-wrap items-center gap-x-3 gap-y-1">
        <span className="text-3xl font-bold text-sale-price">
          {formatPrice(product.price, product.currency)}
        </span>
        <span className="text-lg text-muted-foreground line-through">
          {formatPrice(product.originalPrice, product.currency)}
        </span>
        <Badge className="bg-sale-price text-primary-foreground">
          -{product.discountPercent}%
        </Badge>
      </div>

      {/* Stock */}
      <div
        className={cn(
          "flex items-center gap-2 text-sm font-medium",
          stock.className
        )}
      >
        <span className="size-2 rounded-full bg-current" aria-hidden />
        {stock.label}
      </div>

      <Separator />

      {/* Color selector */}
      <div className="flex flex-col gap-3">
        <div className="flex items-center gap-2">
          <Label className="text-sm font-medium">Color</Label>
          <span className="text-sm text-muted-foreground">
            {selectedColor?.name}
          </span>
        </div>
        <RadioGroup
          value={color}
          onValueChange={setColor}
          className="flex flex-wrap gap-3"
          aria-label="Color"
        >
          {product.colors.map((c) => (
            <Label
              key={c.id}
              htmlFor={`color-${c.id}`}
              className="group relative grid size-9 cursor-pointer place-items-center rounded-full"
            >
              <RadioGroupItem
                id={`color-${c.id}`}
                value={c.id}
                aria-label={c.name}
                className="peer sr-only"
              />
              <span
                className={cn(
                  "size-7 rounded-full border",
                  TRANSITION,
                  "motion-safe:group-hover:scale-110 motion-safe:group-active:scale-95",
                  "peer-data-[state=checked]:ring-2 peer-data-[state=checked]:ring-primary peer-data-[state=checked]:ring-offset-2 peer-data-[state=checked]:ring-offset-background",
                  "peer-focus-visible:ring-[3px] peer-focus-visible:ring-ring peer-focus-visible:ring-offset-2 peer-focus-visible:ring-offset-background"
                )}
                style={{ backgroundColor: c.swatch }}
                aria-hidden
              />
              <Check
                className={cn(
                  "pointer-events-none absolute size-4 text-primary-foreground opacity-0",
                  "transition-opacity duration-[var(--duration-fast)] ease-[var(--ease-out)] motion-reduce:transition-none",
                  "peer-data-[state=checked]:opacity-100"
                )}
                aria-hidden
              />
            </Label>
          ))}
        </RadioGroup>
      </div>

      {/* Size selector */}
      <div className="flex flex-col gap-3">
        <Label className="text-sm font-medium">Size</Label>
        <RadioGroup
          value={size}
          onValueChange={setSize}
          className="flex flex-wrap gap-2"
          aria-label="Size"
        >
          {product.sizes.map((s) => (
            <Label
              key={s.id}
              htmlFor={`size-${s.id}`}
              className={cn(
                "inline-flex h-11 min-w-11 select-none items-center justify-center rounded-md border px-3 text-sm font-medium",
                TRANSITION,
                s.available
                  ? cn(
                      "cursor-pointer hover:border-primary hover:bg-accent hover:text-accent-foreground",
                      "has-[[data-state=checked]]:border-primary has-[[data-state=checked]]:bg-primary has-[[data-state=checked]]:text-primary-foreground has-[[data-state=checked]]:hover:bg-primary",
                      "has-[:focus-visible]:ring-[3px] has-[:focus-visible]:ring-ring has-[:focus-visible]:ring-offset-2 has-[:focus-visible]:ring-offset-background",
                      PRESS
                    )
                  : "cursor-not-allowed border-dashed text-muted-foreground/40 line-through"
              )}
            >
              <RadioGroupItem
                id={`size-${s.id}`}
                value={s.id}
                disabled={!s.available}
                className="sr-only"
              />
              {s.label}
            </Label>
          ))}
        </RadioGroup>
      </div>

      {/* Buy actions */}
      <div className="flex flex-col gap-2">
        <div className="flex flex-col gap-3 sm:flex-row">
          <span className={cn("flex-1", !canAdd && "cursor-not-allowed")}>
            <Button
              size="lg"
              onClick={addToCart}
              disabled={!canAdd || pending}
              aria-busy={pending}
              className={cn("h-12 w-full text-base", PRESS)}
            >
              {pending ? (
                <Loader2 className="animate-spin" />
              ) : (
                <ShoppingCart />
              )}
              {pending ? "Adding…" : "Add to cart"}
            </Button>
          </span>
          <Button
            size="lg"
            variant="outline"
            onClick={toggleWishlist}
            aria-pressed={wishlisted}
            aria-label={wishlisted ? "Remove from wishlist" : "Add to wishlist"}
            className={cn(
              "h-12 sm:w-12",
              PRESS,
              wishlisted && "border-primary text-primary hover:text-primary"
            )}
          >
            <Heart
              className={cn(
                TRANSITION,
                wishlisted && "fill-primary text-primary"
              )}
            />
            <span className="sm:hidden">
              {wishlisted ? "Wishlisted" : "Wishlist"}
            </span>
          </Button>
        </div>
        {!size ? (
          <p className="text-xs text-muted-foreground" aria-live="polite">
            Select a size to add to cart.
          </p>
        ) : null}
      </div>

      {/* Trust badges */}
      <ul className="grid grid-cols-1 gap-3 sm:grid-cols-3">
        {TRUST_BADGES.map((badge) => (
          <li
            key={badge.title}
            className="flex items-center gap-3 rounded-lg border p-3 sm:flex-col sm:items-start sm:gap-1.5"
          >
            <badge.icon
              className="size-5 shrink-0 text-muted-foreground"
              aria-hidden
            />
            <div className="min-w-0">
              <p className="text-sm font-medium">{badge.title}</p>
              <p className="text-xs text-muted-foreground">{badge.detail}</p>
            </div>
          </li>
        ))}
      </ul>
    </div>
  );
}

import { cn } from "@/lib/utils";
import { Card, CardContent } from "@/components/ui/card";
import {
  formatPrice,
  type RelatedProduct,
} from "@/registry/new-york/blocks/product-detail/lib/products";
import {
  FOCUS_RING,
  TRANSITION,
} from "@/registry/new-york/blocks/product-detail/lib/motion";
import { ProductIcon } from "@/registry/new-york/blocks/product-detail/components/product-icon";
import { StarRating } from "@/registry/new-york/blocks/product-detail/components/star-rating";

export function ProductCard({ product }: { product: RelatedProduct }) {
  const onSale = product.originalPrice != null;

  return (
    <Card
      className={cn(
        "group overflow-hidden py-0",
        TRANSITION,
        "hover:border-primary/40 hover:shadow-md"
      )}
    >
      <CardContent className="flex flex-col gap-3 p-0">
        <a
          href="#"
          className={cn("flex flex-col gap-3 rounded-xl", FOCUS_RING)}
          aria-label={product.name}
        >
          <div className="aspect-square overflow-hidden border-b bg-muted">
            <ProductIcon
              icon={product.icon}
              className={cn(
                "size-full rounded-none",
                TRANSITION,
                "motion-safe:group-hover:scale-105"
              )}
              iconClassName="size-12"
            />
          </div>
          <div className="flex flex-col gap-1.5 px-4 pb-4">
            <span className="text-xs tracking-wide text-muted-foreground uppercase">
              {product.category}
            </span>
            <h3 className="text-sm font-medium">{product.name}</h3>
            <div className="flex items-center gap-1.5 text-xs text-muted-foreground">
              <StarRating rating={product.rating} starClassName="[&_svg]:size-3.5" />
              <span>({product.reviewCount})</span>
            </div>
            <div className="mt-1 flex items-center gap-2">
              <span
                className={cn(
                  "text-sm font-semibold",
                  onSale ? "text-sale-price" : "text-price"
                )}
              >
                {formatPrice(product.price)}
              </span>
              {onSale ? (
                <span className="text-xs text-muted-foreground line-through">
                  {formatPrice(product.originalPrice!)}
                </span>
              ) : null}
            </div>
          </div>
        </a>
      </CardContent>
    </Card>
  );
}

"use client";

import {
  Carousel,
  CarouselContent,
  CarouselItem,
  CarouselNext,
  CarouselPrevious,
} from "@/components/ui/carousel";
import type { RelatedProduct } from "@/registry/new-york/blocks/product-detail/lib/products";
import { ProductCard } from "@/registry/new-york/blocks/product-detail/components/product-card";

export function RelatedProducts({ products }: { products: RelatedProduct[] }) {
  return (
    <section aria-label="You may also like" className="flex flex-col gap-6">
      <div className="flex items-center justify-between gap-4">
        <h2 className="text-2xl font-semibold tracking-tight">
          You May Also Like
        </h2>
      </div>

      <Carousel opts={{ align: "start" }} className="w-full">
        <CarouselContent className="-ml-4">
          {products.map((product) => (
            <CarouselItem
              key={product.id}
              className="basis-1/2 pl-4 sm:basis-1/3 lg:basis-1/4"
            >
              <ProductCard product={product} />
            </CarouselItem>
          ))}
        </CarouselContent>
        <CarouselPrevious className="hidden sm:inline-flex" />
        <CarouselNext className="hidden sm:inline-flex" />
      </Carousel>
    </section>
  );
}

import { Layers, Package, Ruler, Shirt, Sparkles } from "lucide-react";

import { cn } from "@/lib/utils";
import type { ProductImage } from "@/registry/new-york/blocks/product-detail/lib/products";

const ICONS = {
  shirt: Shirt,
  sparkles: Sparkles,
  layers: Layers,
  ruler: Ruler,
  package: Package,
} as const;

/**
 * Placeholder visual for a product image. Renders a token-styled tile with a
 * lucide icon; swap for real imagery in a consumer app.
 */
export function ProductIcon({
  icon,
  className,
  iconClassName,
}: {
  icon: ProductImage["icon"];
  className?: string;
  iconClassName?: string;
}) {
  const Icon = ICONS[icon];
  return (
    <div
      className={cn(
        "flex items-center justify-center bg-muted text-muted-foreground",
        className
      )}
    >
      <Icon className={cn("size-10", iconClassName)} aria-hidden />
    </div>
  );
}

import { Star } from "lucide-react";

import { cn } from "@/lib/utils";

/**
 * Read-only star rating. Filled portion uses the `rating-star` token; the empty
 * track uses a muted token. Values render to the nearest half star.
 */
export function StarRating({
  rating,
  className,
  starClassName,
}: {
  rating: number;
  className?: string;
  starClassName?: string;
}) {
  const rounded = Math.round(rating * 2) / 2;

  return (
    <div
      className={cn("flex items-center gap-0.5", className)}
      role="img"
      aria-label={`Rated ${rating} out of 5`}
    >
      {Array.from({ length: 5 }).map((_, i) => {
        const fill = Math.max(0, Math.min(1, rounded - i)); // 0, 0.5, or 1
        return (
          <span key={i} className={cn("relative inline-flex", starClassName)}>
            <Star className="size-4 text-muted-foreground/40" aria-hidden />
            {fill > 0 ? (
              <span
                className="absolute inset-0 overflow-hidden"
                style={{ width: `${fill * 100}%` }}
              >
                <Star
                  className="size-4 fill-rating-star text-rating-star"
                  aria-hidden
                />
              </span>
            ) : null}
          </span>
        );
      })}
    </div>
  );
}

/**
 * Mock data for the product-detail block.
